/*
 * A180636  Positive integers that are divisible by neither 8k-1 nor 8k+1, for
 *          all k > 0.
 * https://oeis.org/A180636
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) is the nth positive integer that is NOT divisible by any
 *            integer ≡ 1 or 7 (mod 8). The sequence is generated by sieving
 *            all integers up to a limit until enough terms have been
 *            collected
 * Range:     u8 n <= 77, u16 n <= 5000, u32 n <= 5000, u64 n <= 5000,
 *            u128 n <= 5000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>

#ifdef __cplusplus
#  define PTR_CAST(type, ptr) reinterpret_cast<type*>(ptr)
#else
#  define PTR_CAST(type, ptr) ((type*)(ptr))
#endif

/* Global state for incremental, memoised sieving */
static idx_t current_limit = 0;   /* maximum integer already sieved */
static seq_t *seq_arr = NULL;     /* array of sequence terms */
static size_t seq_len = 0;        /* number of terms stored */

/* Rebuilds the sieve and the sequence up to at least new_limit. */
static void recompute(idx_t new_limit)
{
    if (new_limit <= current_limit) return;

    /* Mark all numbers ≤ new_limit that are divisible by a ≡1 or 7 (mod 8) */
    size_t N = new_limit + 1;
    bool *bad = PTR_CAST(bool, calloc(N, sizeof(bool)));
    if (!bad) return;  /* allocation failure → abort silently */

    for (idx_t d = 7; d <= new_limit; ++d)
    {
        /* test whether d ≡ 1 or 7 mod 8 */
        if ((((size_t)d & 7ULL) == 1U) || (((size_t)d & 7ULL) == 7U))
        {
            for (idx_t m = d; m <= new_limit; m += d)
                bad[m] = true;
        }
    }

    /* Count how many numbers survive the sieve */
    size_t new_count = 0;
    for (idx_t m = 1; m <= new_limit; ++m)
        if (!bad[m]) ++new_count;

    /* Allocate new sequence array and fill it */
    seq_t *new_seq = PTR_CAST(seq_t, malloc(new_count * sizeof(seq_t)));
    if (!new_seq) { free(bad); return; }  /* allocation failure */

    size_t idx = 0;
    for (idx_t m = 1; m <= new_limit; ++m)
        if (!bad[m]) new_seq[idx++] = (seq_t)m;

    /* Clean up old data and update global state */
    free(bad);
    free(seq_arr);
    seq_arr = new_seq;
    seq_len = new_count;
    current_limit = new_limit;
}

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;  /* sequence is 1‑indexed */

    /* Ensure we have computed at least n terms */
    while (seq_len < (size_t)n)
    {
        /* Increase the sieving limit: at least double the current
           limit or at least twice the required index, whichever is larger. */
        idx_t target = current_limit * 2;
        if (target < n * 2) target = n * 2;
        if (target == 0) target = n * 2;  /* first call when limit == 0 */
        recompute(target);
        /* In the unlikely event that the density is very low,
           further increase the limit until enough terms are found. */
    }

    return seq_arr[n - 1];
}
